Value.Calculation:
Let ( [
	~v = JSONGetElement ( $p ; "scopeId" )
] ;
	If ( IsEmpty ( ~v ) or Left ( ~v ; 1 ) = "?" ; Get ( LayoutNumber ) ; ~v )
)

Let ( [
	~name = JSONGetElement ( $p ; "name" ) ;
	~clu  = JSONGetElement ( $p ; "cluster" ) ;
	~view = JSONGetElement ( $p ; "view" ) ;
	d0 = "{}" ;
	d1 = If ( not IsEmpty ( ~name ) and Left ( ~name ; 1 ) ≠ "?" ; JSONSetElement ( d0 ; "name" ; ~name ; JSONString ) ; d0 ) ;
	d2 = If ( not IsEmpty ( ~clu )  and Left ( ~clu ; 1 )  ≠ "?" ; JSONSetElement ( d1 ; "cluster" ; ~clu ; JSONString ) ; d1 ) ;
	d3 = If ( not IsEmpty ( ~view ) and Left ( ~view ; 1 ) ≠ "?" ; JSONSetElement ( d2 ; "view" ; ~view ; JSONString ) ; d2 )
] ;
	d3
)

Step.Calculation:
JSONSetElement ( "{}" ;
	[ "scope"   ; "layouts" ; JSONString ] ;
	[ "scopeId" ; $scopeId  ; JSONString ] ;
	[ "draft"   ; $draft    ; JSONObject ] ;
	[ "reload"  ; True      ; JSONBoolean ]
)
